__NUXT_JSONP__("/finanzas-publicas/eventos/el_paquete_economico_y_las_prioridades_del_gobierno_de_claudia_sheinbaum", (function(a,b,c,d){return {data:[{post:{slug:"el_paquete_economico_y_las_prioridades_del_gobierno_de_claudia_sheinbaum",title:"El paquete económico y las prioridades del gobierno de Claudia Sheinbaum",date:"2024-12-11T19:13:02.279Z",img:"https:\u002F\u002Fucarecdn.com\u002F5392db5f-29aa-4bee-ae3b-ffb45aacd9fd\u002F","img-alt":"Liliana Alvarado",autor:"Ethos",category:"finanzas-publicas",extracto:"Las prioridades reflejadas en el Paquete Económico 2025 no empatan con los compromisos que hizo la presidenta Claudia Sheinbaum en campaña y al asumir el cargo, señaló Liliana Alvarado, directora de Ethos, en la conferencia de prensa organizada por México Evalúa.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En conferencia de prensa sobre el Paquete Económico 2025, organizada por México Evalúa, Lilliana Alvarado, directora de Ethos, expresó que no hay una relación clara entre los compromisos de la presidenta Claudia Sheinbaum y las prioridades que se observan en el presupuesto para el 2025."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el tema de la ciencia, recordó que hubo un recorte del presupuesto a los 26 centros de investigación que se tienen en ciencia, tecnología, humanidades e innovación. Se hizo, por ejemplo, un recorte de 12% al CIDE."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Mientras tanto, en el combate a la corrupción, de acuerdo con el Anexo Transversal Anticorrupción, se ha reducido el presupuesto 9% mientras los índices internacionales nos siguen mostrando que la corrupción en México va en ascenso."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Liliana Alvarado también habló sobre el Sistema Integral de Cuidados, e indicó que si bien se ha dado más presupuesto al servicio de guarderías y a las estancias del bienestar, se redujo el presupuesto del DIF nacional y para los programas de atención a personas con discapacidad."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Y destacó que había expectativas sobre la mitigación del cambio climático, el impulso a las energías renovables, pero el Anexo Transversal en materia de Medio Ambiente, permite observar que esto no se refleja en el presupuesto. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, explicó que el Paquete Económico no está blindado contra la llegada de Donald Trump a la presidencia de Estados Unidos, ni contra contingencias internas y externas. Por ejemplo, un tema al que supuestamente se le está apostando es el nearshoring para atraer la inversión y fortalecer el crecimiento económico. Sin embargo, el gasto en inversión se redujo. "}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“No se invierte en obras estratégicas que vayan en la misma dirección del nearshoring, como la infraestructura en el agua, sobre todo en la zona norte del país. Por el contrario, el presupuesto para las obras de infraestructura de la Conagua caerá 50 por ciento”, dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Y señaló que un tema importante ante las amenazas eventuales para México es la reforma fiscal, de la que ya se ha hablado y en corto se dice que sí se realizará. “Un tema fundamental es cuándo, pues esta apuesta a una mayor tecnología y a la digitalización para el incremento de la recaudación no va a rendir los frutos que estamos esperando”, dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En la conferencia también participaron Mariana Campos, directora de México Evalúa; Jorge Cano, coordinador del programa de Gasto Público en México Evalúa; Carlos Ramírez, socio y co-director de Integralia; y el periodista Mario Maldonado, como moderador."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fel_paquete_economico_y_las_prioridades_del_gobierno_de_claudia_sheinbaum",extension:".md",createdAt:"2025-04-23T06:21:15.372Z",updatedAt:"2025-04-23T06:21:15.373Z"}}],fetch:{},mutations:[]}}("text","element","p","\n")));